'use strict'

/*
 * The one door into the parsers, and what it says about a document it could not read.
 *
 * The reason this file exists is the difference between two things that look identical
 * in a database: a document with no text, and a document whose pages are pictures. Filed
 * the same way, the second makes a person search for a phrase they can see on the page
 * and find nothing, with no explanation. So the interesting tests here are the ones
 * about images and about `summariseExtraction`, not the ones that check dispatch table
 * wiring.
 *
 * The fixtures are generated by the shared builder rather than committed, because a
 * binary PDF in a repository cannot be reviewed in a diff.
 */

const test = require('node:test')
const assert = require('node:assert/strict')

const api = require('../../../../build/main/ipc.cjs')
const fixtures = require('./fixtures/build.cjs')

for (const name of [
  'extractDocument',
  'summariseExtraction',
  'registerOcrEngine',
  'currentOcrEngine',
  'ocrAvailable',
]) {
  assert.equal(typeof api[name], 'function', `${name} must be exported by the main bundle`)
}

/** Every test that registers an engine must leave the app as it found it. */
function withNoEngine () {
  api.registerOcrEngine(null)
}

test('each kind is sent to its own parser and comes back with its text', async () => {
  withNoEngine()

  const pdf = await api.extractDocument('pdf', fixtures.buildPdf([{ lines: ['The loft quotation is premium work.'] }]))
  assert.match(pdf.sections.map((section) => section.text).join(' '), /premium work/)
  assert.equal(pdf.sections[0].page, 1, 'a PDF page must keep its number')

  const md = await api.extractDocument('md', Buffer.from('# Pricing\n\nThe quotation expires on Friday.\n'))
  assert.equal(md.sections.at(-1).section, 'Pricing')

  const csv = await api.extractDocument('csv', Buffer.from('name,amount\nTilley,1200\n'))
  assert.match(csv.sections[0].text, /Tilley\t1200|\t1200/)

  const docx = await api.extractDocument('docx', fixtures.buildDocx({
    paragraphs: [{ text: 'Survey notes', style: 'Heading1' }, { text: 'The stairwell needs painting.' }],
  }))
  assert.equal(docx.sections.at(-1).section, 'Survey notes')

  const xlsx = await api.extractDocument('xlsx', fixtures.buildXlsx({
    sheets: [{ name: 'Rent roll', rows: [['Unit', 'Rent'], ['Loft 1', 1200]] }],
  }))
  assert.equal(xlsx.sections.at(-1).section, 'Rent roll')

  const pptx = await api.extractDocument('pptx', fixtures.buildPptx({
    slides: [{ lines: ['Tilley refurbishment'], notes: 'Mention the Friday deadline.' }],
  }))
  assert.match(pptx.sections.map((section) => section.text).join(' '), /Friday deadline/)
})

test('an image with no engine installed is reported as a page needing OCR, not as an empty document', async () => {
  withNoEngine()

  const png = Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    Buffer.alloc(32),
  ])
  const result = await api.extractDocument('image', png)

  assert.deepEqual(result.sections, [], 'nothing may be invented from a picture')
  assert.deepEqual(result.ocrPending, [1], 'the page must be named as unread')
  assert.equal(api.ocrAvailable(), false)
})

test('an image with an engine is read, and the engine\'s words become the text', async () => {
  api.registerOcrEngine({
    name: 'test-engine',
    read: async () => '  Receipt for repointing, 1200 pounds.  ',
  })

  try {
    const result = await api.extractDocument('image', Buffer.alloc(64, 1))
    assert.equal(result.sections.length, 1)
    assert.equal(result.sections[0].text, 'Receipt for repointing, 1200 pounds.')
    // A photograph of a receipt has no page to turn to, so it must not claim page 1.
    assert.equal(result.sections[0].page, null)
    assert.deepEqual(result.ocrPending, [])
    assert.equal(api.ocrAvailable(), true)
    assert.equal(api.currentOcrEngine().name, 'test-engine')
  } finally {
    withNoEngine()
  }
})

test('an engine that fails, and an engine that reads nothing, are told apart', async () => {
  api.registerOcrEngine({ name: 'failing', read: async () => { throw new Error('cannot read') } })
  try {
    await assert.rejects(
      () => api.extractDocument('image', Buffer.alloc(16, 2)),
      (error) => error.failure === 'unreadable',
      'an engine failure must become a fixed token, never the engine\'s own message',
    )
  } finally {
    withNoEngine()
  }

  api.registerOcrEngine({ name: 'blank', read: async () => '   \n ' })
  try {
    const result = await api.extractDocument('image', Buffer.alloc(16, 3))
    // A picture with no words in it is still unread, and must not be filed as a document
    // holding one empty section.
    assert.deepEqual(result.sections, [])
    assert.deepEqual(result.ocrPending, [1])
  } finally {
    withNoEngine()
  }
})

test('a file that is not the kind it claims is refused rather than guessed at', async () => {
  // The stored kind is a claim; the bytes are the evidence. A PDF-sized blob under the
  // `docx` kind must not reach the office parser, which would report a corrupt archive.
  await assert.rejects(
    () => api.extractDocument('docx', Buffer.from('%PDF-1.4 not a zip at all')),
    (error) => error.failure === 'unreadable',
  )

  await assert.rejects(
    () => api.extractDocument('pdf', Buffer.from('plain text, not a pdf')),
    (error) => error.failure === 'unreadable',
  )
})

test('an empty file, and a kind this build does not read, are refused', async () => {
  withNoEngine()
  await assert.rejects(() => api.extractDocument('txt', Buffer.alloc(0)), (error) => error.failure === 'unreadable')
  await assert.rejects(
    () => api.extractDocument('spreadsheet_of_the_future', Buffer.from('x')),
    (error) => error.failure === 'unsupported',
  )
})

test('a document whose every page is a picture is judged unread, not empty', async () => {
  withNoEngine()

  const scanned = await api.extractDocument('pdf', fixtures.buildScannedPdf(3))
  assert.equal(scanned.sections.length, 0, 'a scan has no text layer to read')
  assert.deepEqual(scanned.ocrPending, [1, 2, 3])

  const summary = api.summariseExtraction(scanned)
  assert.equal(summary.entirelyUnread, true, 'every page being a picture means the document was not read')
  assert.equal(summary.characters, 0)
})

test('a partly scanned document is read, and names only the pages it could not see', async () => {
  withNoEngine()

  const mixed = await api.extractDocument('pdf', fixtures.buildPdf([
    { lines: ['The rear elevation needs repointing.'] },
    { imageOnly: true },
    { lines: ['The stairwell needs painting.'] },
  ]))

  assert.equal(mixed.sections.length, 2, 'the readable pages must survive')
  assert.deepEqual(mixed.ocrPending, [2])

  const summary = api.summariseExtraction(mixed)
  assert.equal(summary.entirelyUnread, false, 'a partly readable document was read')
  assert.ok(summary.characters > 0)
  // The one page that was a picture must still be reported, so the screen can say so.
  assert.deepEqual(summary.ocrPending, [2])
})

test('a text-only document is not accused of having unread pages', async () => {
  withNoEngine()
  const result = await api.extractDocument('txt', Buffer.from('The quotation expires on Friday.'))
  const summary = api.summariseExtraction(result)

  assert.equal(summary.entirelyUnread, false)
  assert.deepEqual(summary.ocrPending, [])
  assert.equal(summary.characters, 'The quotation expires on Friday.'.length)
})
